files.../tools/g++:
#!/bin/sh
case "$*" in
  *--version*|*-dump*) exec /usr/bin/g++ "$@" ;;
  *exit3.cpp*) exit 3 ;;
  *silent1.cpp*) exit 1 ;;
  *garbage.cpp*) echo 'this is not a compiler diagnostic' >&2; exit 1 ;;
  *signal.cpp*) kill -KILL $$ ;;
esac
exec /usr/bin/g++ "$@"

